fn encode(message: Vec<char>) -> Vec<char> {
    // Helper function to check if a char is a vowel
    fn is_vowel(c: char) -> bool {
        matches!(c, 'a' | 'e' | 'i' | 'o' | 'u' | 
                     'A' | 'E' | 'I' | 'O' | 'U')
    }

    // Helper function to map vowels to their replacements
    fn map_vowel(c: char) -> char {
        match c {
            'a' => 'c',
            'e' => 'g',
            'i' => 'k',
            'o' => 'q',
            'u' => 'w',
            'A' => 'C',
            'E' => 'G',
            'I' => 'K',
            'O' => 'Q',
            'U' => 'W',
            _ => c, // Should never occur if input is guaranteed vowels here
        }
    }

    // Helper function to swap case of a letter
    fn swap_case(c: char) -> char {
        if c.is_ascii_uppercase() {
            c.to_ascii_lowercase()
        } else {
            c.to_ascii_uppercase()
        }
    }

    // Process each character according to the rules
    message.into_iter().map(|ch| {
        if ch == ' ' {
            ' '
        } else if is_vowel(ch) {
            // Map vowel, then swap case
            let replaced = map_vowel(ch);
            swap_case(replaced)
        } else {
            // Consonant: swap case
            swap_case(ch)
        }
    }).collect()
}